import { computed, mount, selector, signal } from 'kerfjs';
import { Combobox } from '@kerfjs/ui/combobox';
import { wireComboboxes } from '@kerfjs/ui/wire-comboboxes';

type Source = 'incoming' | 'outgoing';
type RecordData = { id: number; label: string };
let nextPickerId = 0;

export function mountStudy(
  root: HTMLElement,
  onCommit: (value: string) => void,
  mark: (kind: 'row') => void,
) {
  const app = document.createElement('div');
  const inspector = document.createElement('section');
  const list = document.createElement('section');
  app.append(inspector, list);
  root.append(app);

  const counts = { incoming: signal(4), outgoing: signal(7) };
  const activeSource = signal<Source>('incoming');
  const badge = computed(() => `${counts[activeSource.value].value} crates`);
  const stopInspector = mount(inspector, () => (
    <div>
      <output data-badge="" title={badge}>{badge}</output>
      <input data-note="" aria-label="Note" />
    </div>
  ));

  const selectedId = signal<number | null>(null);
  const isSelected = selector(selectedId);

  function renderRow(
    id: number,
    label: ReturnType<typeof signal<string>>,
    ariaSelected: ReturnType<typeof computed<string>>,
  ) {
    mark('row');
    return (
      <div data-key={id} data-row={id} aria-selected={ariaSelected}>
        <span>{label}</span>
        <input aria-label={`Edit record ${id}`} />
      </div>
    );
  }

  function mountRow({ id, label }: RecordData) {
    const host = document.createElement('div');
    list.append(host);
    const currentLabel = signal(label);
    const selected = isSelected(id);
    const ariaSelected = computed<string>(() => selected.value ? 'true' : 'false');
    const stop = mount(host, () => renderRow(id, currentLabel, ariaSelected));
    return { host, label: currentLabel, stop };
  }

  const rows = new Map<number, ReturnType<typeof mountRow>>();
  let order: number[] = [];
  let disposed = false;

  function placeRows(ids: number[]) {
    const active = list.ownerDocument.activeElement;
    const editor = active instanceof HTMLInputElement && list.contains(active) ? active : null;
    const start = editor?.selectionStart;
    const end = editor?.selectionEnd;
    const direction = editor?.selectionDirection;

    let cursor = list.firstElementChild;
    for (const id of ids) {
      const { host } = rows.get(id)!;
      if (host === cursor) {
        cursor = cursor.nextElementSibling;
      } else {
        list.insertBefore(host, cursor);
      }
    }
    order = ids;

    if (editor && list.contains(editor)) {
      if (list.ownerDocument.activeElement !== editor) editor.focus({ preventScroll: true });
      if (typeof start === 'number' && typeof end === 'number' && (
        editor.selectionStart !== start || editor.selectionEnd !== end ||
        editor.selectionDirection !== direction
      )) {
        editor.setSelectionRange(start, end, direction ?? 'none');
      }
    }
  }

  function refetch(records: RecordData[]) {
    if (disposed) return;
    const ids = new Set(records.map(record => record.id));
    for (const [id, row] of rows) {
      if (!ids.has(id)) {
        row.stop();
        row.host.remove();
        rows.delete(id);
      }
    }
    for (const record of records) {
      const row = rows.get(record.id);
      if (row) {
        row.label.value = record.label;
      } else {
        rows.set(record.id, mountRow(record));
      }
    }
    placeRows([...ids]);
  }

  refetch([
    { id: 1, label: 'One' },
    { id: 2, label: 'Two' },
    { id: 3, label: 'Three' },
    { id: 4, label: 'Four' },
  ]);

  const pickerId = `study-fruit-${++nextPickerId}`;
  const suggestions = ['Apricot', 'Blueberry', 'Cherry'];
  let picker: { root: HTMLElement; stop: () => void } | undefined;

  function open() {
    if (disposed || picker) return;
    const pickerRoot = document.createElement('div');
    app.append(pickerRoot);
    const stopField = mount(pickerRoot, () => (
      <Combobox id={pickerId} label="Fruit" suggestions={suggestions} createLabel={false} />
    ));
    const stopBehavior = wireComboboxes(pickerRoot, {
      onCommit: ({ value }) => {
        if (picker?.root === pickerRoot) onCommit(value);
      },
    });
    picker = {
      root: pickerRoot,
      stop() {
        stopBehavior();
        stopField();
        pickerRoot.remove();
      },
    };
  }

  function close() {
    const current = picker;
    picker = undefined;
    current?.stop();
  }

  return {
    count(source: Source, value: number) {
      if (!disposed) counts[source].value = value;
    },
    mode(source: Source) {
      if (!disposed) activeSource.value = source;
    },
    select(id: number) {
      if (!disposed) selectedId.value = id;
    },
    refetch,
    swap() {
      if (disposed || order.length < 2) return;
      const [first, second, ...rest] = order;
      placeRows([second, first, ...rest]);
    },
    open,
    close,
    dispose() {
      if (disposed) return;
      disposed = true;
      close();
      for (const row of rows.values()) row.stop();
      rows.clear();
      order = [];
      stopInspector();
      app.remove();
    },
  };
}
